use App\Modules\Blog\Domain\BlogEvent;
use App\Modules\Blog\Domain\BlogStatus;
use App\Modules\Blog\Infrastructure\BlogRepository;
use App\Platform\Access\AccessService;
use App\Platform\Audit\AuditLogger;
use App\Platform\Identity\Domain\User;
use App\Platform\Identity\Infrastructure\UserRepository;
use App\Platform\Messaging\Outbox;
use App\Platform\Queue\JobQueue;
use App\Shared\Domain\Exception\ConflictException;
use App\Shared\Domain\Exception\NotFoundException;
use App\Shared\Domain\Exception\ValidationException;
use App\Shared\Domain\Uuid;
use App\Shared\Infrastructure\Database\Page;
use Yiisoft\Db\Connection\ConnectionInterface;
use Yiisoft\Db\Query\Query;

/**
 * Blog use cases shared by the Admin UI, Web UI and REST API.
 *
 * Security (server-side, default deny):
 *  - every operation asserts its RBAC permission (blog.view|create|update|delete),
 *  - tenant isolation: without `tenants.cross` only the actor's tenant is visible; foreign ids → 404 (IDOR),
 *  - updates are optimistic-locked (version) → 409 stale_version.
 * Each change writes the row, the audit record and the outbox event (Kafka topic blog.events) in ONE transaction.
 */
final class BlogService
{
    public const REPORT_JOB = 'blog.report.generate';

    public function __construct(
        private readonly BlogRepository $repository,
        private readonly UserRepository $users,
        private readonly AccessService $access,
        private readonly AuditLogger $audit,
        private readonly ConnectionInterface $db,
        private readonly Outbox $outbox,
        private readonly BlogWorkflow $workflow,
        private readonly JobQueue $queue,
    ) {}

    public function search(User $actor, array $filters, int $page, int $perPage, ?string $sort): Page
    {
        $this->access->assert($actor->id, 'blog.view');
        return $this->repository->search($filters, $page, $perPage, $sort, $this->tenantRestriction($actor));
    }

    public function get(User $actor, string $id): Blog
    {
        $this->access->assert($actor->id, 'blog.view');
        return $this->load($actor, $id);
    }

    /** @param array<string,mixed> $input */
    public function create(User $actor, array $input): Blog
    {
        $this->access->assert($actor->id, 'blog.create');
        $tenantId = $this->resolveTenant($actor, $input);
        $input = $this->resolveUsers($actor, $tenantId, $input, true);
        $entity = Blog::create(Uuid::v7(), $tenantId, $input, $actor->id);
        $this->db->transaction(function () use ($entity, $actor): void {
            $this->repository->insert($entity);
            $this->audit->record('blog.created', 'blog', $entity->id, null, $entity->toArray(), category: 'data');
            $this->publish($entity);
            $this->workflow->start($entity, $actor->id);
        });
        return $this->repository->find($entity->id) ?? $entity;
    }

    /** @param array<string,mixed> $input */
    public function update(User $actor, string $id, array $input, int $expectedVersion): Blog
    {
        $this->access->assert($actor->id, 'blog.update');
        return $this->db->transaction(function () use ($actor, $id, $input, $expectedVersion): Blog {
            $entity = $this->loadForUpdate($actor, $id);
            $this->assertVersion($entity, $expectedVersion);
            $before = $entity->toArray();
            $input = $this->resolveUsers($actor, $entity->tenantId, $input, false);
            $changes = $entity->update($input);
            if ($changes === []) {
                return $entity;
            }
            $this->repository->update($entity, $expectedVersion);
            $after = $this->repository->find($entity->id) ?? $entity;
            $this->audit->record('blog.updated', 'blog', $entity->id, $before, $after->toArray(), ['fields' => array_keys($changes)]);
            $this->publish($entity);
            return $after;
        });
    }

    /** Lifecycle transition (permission blog.update); invalid moves → 409 invalid_transition. */
    public function changeStatus(User $actor, string $id, string $status, ?int $expectedVersion = null, string $comment = ''): Blog
    {
        $to = BlogStatus::tryFrom($status);
        if ($to === null) {
            throw ValidationException::single('status', 'Status must be one of: ' . implode(', ', BlogStatus::values()) . '.');
        }
        $this->access->assert($actor->id, 'blog.update');
        return $this->db->transaction(function () use ($actor, $id, $to, $expectedVersion, $comment): Blog {
            $entity = $this->loadForUpdate($actor, $id);
            $this->assertVersion($entity, $expectedVersion);
            $version = $entity->version();
            $from = $entity->changeStatus($to, $comment);
            $this->repository->update($entity, $version);
            $after = $this->repository->find($entity->id) ?? $entity;
            $this->audit->record(
                'blog.status_changed',
                'blog',
                $entity->id,
                ['status' => $from->value],
                ['status' => $to->value],
                ['from' => $from->value, 'to' => $to->value, 'comment' => $comment],
                severity: $to->isTerminal() ? 'notice' : 'info',
            );
            $this->publish($entity);
            $this->workflow->mirror($after, $from, $to, $actor->id, $comment);
            return $after;
        });
    }

    /** @return array<string,int> status => count (tenant scoped) */
    public function countsByStatus(User $actor): array
    {
        $this->access->assert($actor->id, 'blog.view');
        return $this->repository->countsByStatus($this->tenantRestriction($actor));
    }
    /** Soft delete (permission blog.delete). */
    public function delete(User $actor, string $id, ?int $expectedVersion = null): void
    {
        $this->access->assert($actor->id, 'blog.delete');
        $this->db->transaction(function () use ($actor, $id, $expectedVersion): void {
            $entity = $this->loadForUpdate($actor, $id);
            $this->assertVersion($entity, $expectedVersion);
            $before = $entity->toArray();
            $version = $entity->version();
            $entity->markDeleted();
            $this->repository->update($entity, $version);
            $this->audit->record('blog.deleted', 'blog', $entity->id, $before, null, severity: 'notice');
            $this->publish($entity);
        });
    }

    /**
     * Timeline: the Kafka read model when populated, otherwise the audit trail.
     *
     * @return array{source:string, items:list<array<string,mixed>>}
     */
    public function activity(User $actor, string $id): array
    {
        $entity = $this->get($actor, $id);
        $items = $this->repository->activity($entity->id);
        if ($items !== []) {
            return ['source' => 'read_model', 'items' => $items];
        }
        $items = array_map(static fn(array $r) => [
            'event_type' => $r['action'],
            'summary' => $r['action'],
            'actor_id' => $r['actor_id'],
            'occurred_at' => $r['occurred_at'],
        ], $this->repository->auditTrail($entity->id));
        return ['source' => 'audit', 'items' => $items];
    }

    /**
     * Enqueues the CSV report for the actor's tenant (background job, transactional enqueue).
     *
     * @return array{report_id:string, job_id:string}
     */
    public function requestReport(User $actor, array $filters = []): array
    {
        $this->access->assert($actor->id, 'blog.view');
        $tenantId = $this->resolveTenant($actor, $filters);
        $filters = array_intersect_key($filters, array_flip(['q', ...BlogRepository::FILTERS]));
        unset($filters['tenant_id']);
        return $this->db->transaction(function () use ($actor, $tenantId, $filters): array {
            $reportId = Uuid::v7();
            $this->db->createCommand()->insert('blog_reports', [
                'id' => $reportId,
                'tenant_id' => $tenantId,
                'filters' => json_encode((object) $filters),
                'requested_by' => $actor->id,
            ])->execute();
            $jobId = $this->queue->push(self::REPORT_JOB, ['report_id' => $reportId, 'tenant_id' => $tenantId], [
                'queue' => 'default',
                'tenant_id' => $tenantId,
                'max_attempts' => 3,
                'timeout' => 600,
                'idempotency_key' => 'blog.report:' . $reportId,
            ]);
            $this->db->createCommand()->update('blog_reports', ['job_id' => $jobId], ['id' => $reportId])->execute();
            $this->audit->record('blog.report.requested', 'blog_report', $reportId, null, ['tenant_id' => $tenantId, 'filters' => $filters, 'job_id' => $jobId]);
            return ['report_id' => $reportId, 'job_id' => $jobId];
        });
    }

    /** @return array<string,mixed> report row joined with the job status */
    public function report(User $actor, string $reportId): array
    {
        $this->access->assert($actor->id, 'blog.view');
        if (!Uuid::isValid($reportId)) {
            throw new NotFoundException('Report not found.');
        }
        $row = (new Query($this->db))
            ->select(['r.*', 'job_status' => 'j.status', 'job_error' => 'j.last_error'])
            ->from(['r' => 'blog_reports'])->leftJoin(['j' => 'jobs'], 'j.id = r.job_id')
            ->where(['r.id' => strtolower($reportId)])->one();
        $restriction = $this->tenantRestriction($actor);
        if ($row === null || ($restriction !== null && $row['tenant_id'] !== $restriction)) {
            throw new NotFoundException('Report not found.');
        }
        return $row;
    }

    /** @return list<array<string,mixed>> */
    public function recentReports(User $actor, int $limit = 5): array
    {
        $this->access->assert($actor->id, 'blog.view');
        $q = (new Query($this->db))->select(['id', 'status', 'rows_count', 'size_bytes', 'created_at', 'finished_at'])
            ->from('blog_reports')->orderBy(['created_at' => SORT_DESC])->limit($limit);
        $restriction = $this->tenantRestriction($actor);
        if ($restriction !== null) {
            $q->where(['tenant_id' => $restriction]);
        }
        return $q->all();
    }
    public function tenantRestriction(User $actor): ?string
    {
        if ($this->access->can($actor->id, 'tenants.cross')) {
            return null;
        }
        return $actor->tenantId ?? '00000000-0000-0000-0000-000000000000';
    }

    // ------------------------------------------------------------------ internals

    /** Writes the aggregate's pending domain events to the transactional outbox (same DB transaction). */
    private function publish(Blog $entity): void
    {
        foreach ($entity->pullEvents() as $event) {
            $this->outbox->record(BlogEvent::TOPIC, $event['type'], BlogEvent::AGGREGATE, $entity->id, BlogEvent::payload($entity, $event['payload']));
        }
    }

    private function load(User $actor, string $id): Blog
    {
        $entity = $this->repository->find($id);
        return $this->assertVisible($actor, $entity);
    }

    private function loadForUpdate(User $actor, string $id): Blog
    {
        $entity = $this->repository->findForUpdate($id);
        return $this->assertVisible($actor, $entity);
    }

    private function assertVisible(User $actor, ?Blog $entity): Blog
    {
        $restriction = $this->tenantRestriction($actor);
        if ($entity === null || ($restriction !== null && $entity->tenantId !== $restriction)) {
            // IDOR protection: records of other tenants are reported as non-existent
            throw new NotFoundException('Blog not found.');
        }
        return $entity;
    }

    private function assertVersion(Blog $entity, ?int $expectedVersion): void
    {
        if ($expectedVersion !== null && $expectedVersion !== $entity->version()) {
            throw new ConflictException('The blog was modified by someone else. Reload and try again.', 'stale_version');
        }
    }

    private function resolveTenant(User $actor, array $input): string
    {
        $restriction = $this->tenantRestriction($actor);
        if ($restriction !== null) {
            if ($actor->tenantId === null) {
                throw ValidationException::single('tenant_id', 'Your account is not assigned to a tenant.');
            }
            return $restriction;
        }
        $requested = isset($input['tenant_id']) && is_string($input['tenant_id']) && $input['tenant_id'] !== '' ? strtolower($input['tenant_id']) : null;
        $tenantId = $requested ?? $actor->tenantId
            ?? ((new Query($this->db))->select('id')->from('tenants')->where(['code' => 'default'])->scalar() ?: null);
        if ($tenantId === null || !Uuid::isValid((string) $tenantId)
            || !(new Query($this->db))->from('tenants')->where(['id' => $tenantId, 'status' => 'active'])->exists()) {
            throw ValidationException::single('tenant_id', 'Unknown or inactive tenant.');
        }
        return (string) $tenantId;
    }

    /**
     * User references must be active users of the record's tenant; required ones default to the actor on create.
     *
     * @param array<string,mixed> $input
     * @return array<string,mixed>
     */
    private function resolveUsers(User $actor, string $tenantId, array $input, bool $creating): array
    {
        $errors = [];
        $value = $input['owner_id'] ?? null;
        if (is_string($value) && $value !== '' && Uuid::isValid($value) && $value !== $actor->id) {
            $user = $this->users->find($value);
            if ($user === null || !$user->isActive() || $user->tenantId !== $tenantId) {
                $errors['owner_id'][] = 'Owner must be an active user of the same tenant.';
            } else {
                $input['owner_id'] = $user->id;
            }
        }
        if ($errors !== []) {
            throw new ValidationException($errors);
        }
        return $input;
    }
}
